using Azure.Search.Documents.Indexes;using Azure.Search.Documents.Indexes.Models;
public sealed class SearchIndexProvisioner(SearchIndexClient client,IConfiguration config,ILogger<SearchIndexProvisioner> log){public async Task ProvisionAsync(CancellationToken ct=default){if(!config.GetValue<bool>("AzureSearch:ProvisionIndex"))return;var name=config["AzureSearch:IndexName"]??"document-chunks";var dimensions=config.GetValue<int?>("AzureSearch:EmbeddingDimensions")??1536;var fields=new List<SearchField>{new SimpleField("id",SearchFieldDataType.String){IsKey=true},new SimpleField("TenantId",SearchFieldDataType.String){IsFilterable=true},new SimpleField("DocumentId",SearchFieldDataType.String){IsFilterable=true},new SimpleField("VersionId",SearchFieldDataType.String){IsFilterable=true},new SimpleField("ChunkNumber",SearchFieldDataType.Int32){IsFilterable=true,IsSortable=true},new SearchableField("Text"),new SimpleField("TokenCount",SearchFieldDataType.Int32),new SearchField("ContentVector",SearchFieldDataType.Collection(SearchFieldDataType.Single)){IsSearchable=true,VectorSearchDimensions=dimensions,VectorSearchProfileName="document-vector-profile"},new SimpleField("Citation",SearchFieldDataType.String),new SearchField("AllowedPrincipalIds",SearchFieldDataType.Collection(SearchFieldDataType.String)){IsFilterable=true}};var vector=new VectorSearch();vector.Algorithms.Add(new HnswAlgorithmConfiguration("document-hnsw"));vector.Profiles.Add(new VectorSearchProfile("document-vector-profile","document-hnsw"));var index=new SearchIndex(name,fields){VectorSearch=vector};await client.CreateOrUpdateIndexAsync(index,allowIndexDowntime:false,cancellationToken:ct);log.LogInformation("Ensured Azure AI Search index {IndexName} with {Dimensions} dimensions",name,dimensions);}}
